1	import { pageAbout, pageContact } from "../core/setup.js";
2	import type { GsapGlobal } from "../types/gsap.types.js";
3	import type { IntroManagerDependencies } from "../types/intro.types.js";
4	import type { AboutPageConfig } from "../types/about.types.js";
5	import type { ContactPageConfig } from "../types/contact.types.js";
6	import type { MainPageConfig } from "../types/main.types.js";
7	import type { AppPageConfig } from "../types/runtime.types.js";
8	
9	export class IntroManager {
10	  private readonly _dependencies: IntroManagerDependencies;
11	
12	  constructor(dependencies: IntroManagerDependencies) {
13	    this._dependencies = dependencies;
14	  }
15	
16	  async run(
17	    pageConfig: AppPageConfig,
18	    objectSetupPromise: Promise<void>,
19	    gsap: GsapGlobal | null,
20	  ): Promise<void> {
21	    if (pageConfig.pageId === pageContact) {
22	      await this._dependencies.controller.runContactIntro(
23	        pageConfig as ContactPageConfig,
24	        objectSetupPromise,
25	      );
26	      return;
27	    }
28	
29	    if (!this._dependencies.controller.hasIntro(pageConfig, gsap)) {
30	      await this._dependencies.runAfterLoad(pageConfig, objectSetupPromise);
31	      await this._dependencies.startPagePreviewIfNeeded();
32	      return;
33	    }
34	
35	    if (pageConfig.pageId === pageAbout) {
36	      await this._dependencies.controller.runAboutIntro(
37	        pageConfig as AboutPageConfig,
38	        objectSetupPromise,
39	        gsap!,
40	      );
41	      return;
42	    }
43	
44	    await this._dependencies.controller.runMainIntro(
45	      pageConfig as MainPageConfig,
46	      objectSetupPromise,
47	      gsap!,
48	    );
49	  }
50	}
