1	.no-loading-overlay {
2	  position: fixed;
3	  inset: 0;
4	  z-index: calc(var(--z-index-button-floating) + 10);
5	  display: grid;
6	  place-items: center;
7	  padding: 24px;
8	  background: var(--clr-background-overlay);
9	  opacity: 0;
10	  visibility: hidden;
11	  pointer-events: none;
12	  transition:
13	    opacity var(--transition-fast),
14	    visibility var(--transition-fast);
15	
16	  &[aria-hidden="false"] {
17	    opacity: 1;
18	    visibility: visible;
19	    pointer-events: auto;
20	  }
21	}
22	
23	.no-loading-overlay__panel {
24	  min-width: min(260px, 100%);
25	  max-width: 420px;
26	  display: flex;
27	  align-items: center;
28	  gap: 12px;
29	  padding: 14px 16px;
30	  border-radius: 12px;
31	  background: var(--clr-surface-elevated);
32	  border: 1px solid var(--clr-border-default);
33	  box-shadow: var(--shadow-floating-card);
34	  color: var(--clr-text-body);
35	}
36	
37	.no-loading-overlay__spinner {
38	  width: 18px;
39	  height: 18px;
40	  border-radius: 50%;
41	  border: 2px solid var(--clr-border-default);
42	  border-top-color: var(--clr-trigger-default);
43	  animation: no-loading-spin 0.8s linear infinite;
44	  flex: 0 0 auto;
45	}
46	
47	.no-loading-overlay__text {
48	  color: var(--clr-text-title);
49	  line-height: 1.4;
50	}
51	
52	body.is-loading-action {
53	  cursor: progress;
54	}
55	
56	@keyframes no-loading-spin {
57	  to {
58	    transform: rotate(360deg);
59	  }
60	}
61	
62	@media (prefers-reduced-motion: reduce) {
63	  .no-loading-overlay {
64	    transition: none;
65	  }
66	
67	  .no-loading-overlay__spinner {
68	    animation: none;
69	  }
70	}
