1	import { DOM_CONFIG } from "../config/dom.config.js";
2	import { TimelineController } from "../controller/TimelineController.js";
3	import type { IntroConfig } from "../types/core.types.js";
4	import type { GsapGlobal } from "../types/gsap.types.js";
5	import { ScrollLock } from "../utils/ScrollLock.js";
6	import { IntroCanvas } from "./IntroCanvas.js";
7	
8	const INTRO_DOM_SELECTORS = [
9	  DOM_CONFIG.keys.intro?.title,
10	  DOM_CONFIG.keys.intro?.desc,
11	  DOM_CONFIG.keys.intro?.time,
12	  DOM_CONFIG.keys.intro?.btn,
13	  DOM_CONFIG.keys.intro?.section,
14	].filter((selector): selector is string => typeof selector === "string" && selector.length > 0);
15	const DOM_WAIT_TIMEOUT_MS = 4000;
16	
17	export class IntroOverlay {
18	  constructor(private readonly _config: IntroConfig) {}
19	
20	  async run(params: {
21	    gsap: GsapGlobal;
22	    loadPromise: Promise<unknown>;
23	    onComplete?: () => void | Promise<void>;
24	  }): Promise<void> {
25	    let releaseScrollLock: (() => void) | null = null;
26	    if (this._config.waitForDomSelectors !== false) {
27	      const selectorsReady = await IntroOverlay.waitForDomSelectors(
28	        INTRO_DOM_SELECTORS,
29	        DOM_WAIT_TIMEOUT_MS,
30	      );
31	      if (!selectorsReady) {
32	      }
33	    }
34	
35	    IntroOverlay.show();
36	    const rawTl = params.gsap.timeline({ paused: true });
37	    const controller = new TimelineController(rawTl);
38	
39	    rawTl.eventCallback?.("onStart", () => {
40	      IntroOverlay.show();
41	      releaseScrollLock?.();
42	      releaseScrollLock = ScrollLock.lock();
43	      window.scrollTo({ top: 0, behavior: "auto" });
44	    });
45	
46	    rawTl.progress(0);
47	    this._config.tl(rawTl, {
48	      controller,
49	      loadPromise: params.loadPromise.then(() => undefined),
50	      gsap: params.gsap,
51	    });
52	
53	    await new Promise<void>((resolve) => {
54	      rawTl.eventCallback?.("onComplete", () => {
55	        IntroOverlay.hide();
56	        releaseScrollLock?.();
57	        releaseScrollLock = null;
58	        window.scrollTo({ top: 0, behavior: "auto" });
59	        void (async () => {
60	          try {
61	            await params.onComplete?.();
62	          } finally {
63	            resolve();
64	          }
65	        })();
66	      });
67	      controller.play();
68	    });
69	
70	    controller.dispose();
71	    if (releaseScrollLock !== null) {
72	      const runRelease: () => void = releaseScrollLock;
73	      runRelease();
74	    }
75	  }
76	
77	  dispose(): void {}
78	
79	  static show(): void {
80	    document.documentElement.classList.add("is-intro");
81	    IntroCanvas.ensure();
82	    IntroOverlay._setVisibilityState(true);
83	  }
84	
85	  static hide(): void {
86	    document.documentElement.classList.remove("is-intro");
87	    IntroOverlay._setVisibilityState(false);
88	  }
89	
90	  private static _setVisibilityState(visible: boolean): void {
91	    const section = DOM_CONFIG.keys.intro?.section ?? "#intro";
92	    const element = document.querySelector<HTMLElement>(section);
93	    if (!element) return;
94	    element.classList.toggle("is-hidden", !visible);
95	    element.style.visibility = visible ? "visible" : "hidden";
96	    element.style.pointerEvents = visible ? "auto" : "none";
97	  }
98	
99	  private static waitForDomSelectors(
100	    selectors: string[],
101	    timeoutMs: number,
102	  ): Promise<boolean> {
103	    if (selectors.length === 0) return Promise.resolve(true);
104	    if (typeof document === "undefined") return Promise.resolve(false);
105	
106	    const allReady = (): boolean =>
107	      selectors.every((selector) => document.querySelector(selector));
108	
109	    if (allReady()) return Promise.resolve(true);
110	
111	    return new Promise<boolean>((resolve) => {
112	      const timer = window.setTimeout(() => {
113	        observer.disconnect();
114	        resolve(false);
115	      }, timeoutMs);
116	
117	      const observer = new MutationObserver(() => {
118	        if (!allReady()) return;
119	        observer.disconnect();
120	        window.clearTimeout(timer);
121	        resolve(true);
122	      });
123	
124	      observer.observe(document.documentElement, {
125	        childList: true,
126	        subtree: true,
127	      });
128	    });
129	  }
130	}
