1	import {
2	  INTRO_CANVAS_COLORS,
3	  INTRO_CANVAS_MOTION,
4	  INTRO_CANVAS_RENDER,
5	  INTRO_CANVAS_SELECTORS,
6	} from "../config/intro.config.js";
7	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
8	import type {
9	  IntroCanvasColorStop,
10	  IntroCanvasParticle,
11	} from "../types/intro.types.js";
12	
13	export class IntroCanvas {
14	  private static _instance: IntroCanvas | null = null;
15	
16	  private _particles: IntroCanvasParticle[] = [];
17	  private _currentProgress = 0;
18	  private _lastProgress = 0;
19	  private _lastTime = 0;
20	  private _animationFrameId = 0;
21	
22	  private constructor(
23	    private readonly _canvas: HTMLCanvasElement,
24	    private readonly _context: CanvasRenderingContext2D,
25	    private readonly _percentText: HTMLElement,
26	  ) {
27	    this._resize = this._resize.bind(this);
28	    this._loop = this._loop.bind(this);
29	    this._resize();
30	    window.addEventListener("resize", this._resize);
31	    this._animationFrameId = window.requestAnimationFrame(this._loop);
32	    window.__introProgress = {
33	      set: (value: number) => this.set(value),
34	      reset: () => this.reset(),
35	    };
36	  }
37	
38	  static ensure(): IntroCanvas | null {
39	    if (typeof document === "undefined") return null;
40	    if (IntroCanvas._instance?.isConnected()) return IntroCanvas._instance;
41	    IntroCanvas._instance?.dispose();
42	    const next = IntroCanvas.create();
43	    IntroCanvas._instance = next;
44	    return next;
45	  }
46	
47	  dispose(): void {
48	    if (this._animationFrameId !== 0) {
49	      window.cancelAnimationFrame(this._animationFrameId);
50	      this._animationFrameId = 0;
51	    }
52	    window.removeEventListener("resize", this._resize);
53	    delete window.__introProgress;
54	  }
55	
56	  set(value: number): void {
57	    const next = Math.max(0, Math.min(100, value));
58	    if (next < this._currentProgress) this._particles = [];
59	    this._currentProgress = next;
60	  }
61	
62	  reset(): void {
63	    this._currentProgress = 0;
64	    this._lastProgress = 0;
65	    this._lastTime = 0;
66	    this._particles = [];
67	    this._percentText.textContent = "0";
68	  }
69	
70	  private static create(): IntroCanvas | null {
71	    const canvas = document.querySelector(INTRO_CANVAS_SELECTORS.canvas);
72	    const percentText = document.querySelector(INTRO_CANVAS_SELECTORS.percent);
73	    if (!(canvas instanceof HTMLCanvasElement)) return null;
74	    if (!(percentText instanceof HTMLElement)) return null;
75	    const context = canvas.getContext("2d");
76	    if (!context) return null;
77	    return new IntroCanvas(canvas, context, percentText);
78	  }
79	
80	  private isConnected(): boolean {
81	    return document.contains(this._canvas) && document.contains(this._percentText);
82	  }
83	
84	  private _resize(): void {
85	    const rect = this._canvas.getBoundingClientRect();
86	    const dpr = ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio;
87	    this._canvas.width = rect.width * dpr;
88	    this._canvas.height = rect.height * dpr;
89	    this._context.setTransform(1, 0, 0, 1, 0, 0);
90	    this._context.scale(dpr, dpr);
91	  }
92	
93	  private _loop(timestamp: number): void {
94	    const deltaTime = timestamp - this._lastTime || 16;
95	    this._lastTime = timestamp;
96	    const progressSpeed =
97	      (Math.abs(this._currentProgress - this._lastProgress) /
98	        Math.max(deltaTime, 1)) *
99	      16;
100	
101	    if (
102	      this._currentProgress > INTRO_CANVAS_RENDER.minVisibleProgress &&
103	      this._currentProgress >
104	        this._lastProgress + INTRO_CANVAS_MOTION.progressVelocityThreshold
105	    ) {
106	      const headX = this._mapProgressToX(this._currentProgress, this.getWidth());
107	      this._spawnParticles(
108	        headX,
109	        this.getHeight() / 2,
110	        this.getColorAt(this._currentProgress),
111	        Math.min(progressSpeed, INTRO_CANVAS_MOTION.particleSpeedMax),
112	      );
113	    }
114	
115	    this._lastProgress = this._currentProgress;
116	    this._drawFrame(this._currentProgress, timestamp);
117	    this._animationFrameId = window.requestAnimationFrame(this._loop);
118	  }
119	
120	  private getWidth(): number {
121	    const dpr = ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio;
122	    return this._canvas.width / dpr;
123	  }
124	
125	  private getHeight(): number {
126	    const dpr = ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio;
127	    return this._canvas.height / dpr;
128	  }
129	
130	  private getColorAt(progress: number): readonly [number, number, number] {
131	    for (let i = 0; i < INTRO_CANVAS_COLORS.length - 1; i += 1) {
132	      const current = INTRO_CANVAS_COLORS[i];
133	      const next = INTRO_CANVAS_COLORS[i + 1];
134	      if (progress < current.progress || progress > next.progress) continue;
135	      return this.lerpColor(
136	        current.color,
137	        next.color,
138	        (progress - current.progress) / (next.progress - current.progress),
139	      );
140	    }
141	    return INTRO_CANVAS_COLORS[INTRO_CANVAS_COLORS.length - 1].color;
142	  }
143	
144	  private lerpColor(
145	    from: IntroCanvasColorStop["color"],
146	    to: IntroCanvasColorStop["color"],
147	    ratio: number,
148	  ): [number, number, number] {
149	    return [
150	      Math.round(from[0] + (to[0] - from[0]) * ratio),
151	      Math.round(from[1] + (to[1] - from[1]) * ratio),
152	      Math.round(from[2] + (to[2] - from[2]) * ratio),
153	    ];
154	  }
155	
156	  private rgba(color: readonly [number, number, number], alpha: number): string {
157	    return `rgba(${color[0]},${color[1]},${color[2]},${alpha.toFixed(3)})`;
158	  }
159	
160	  private _spawnParticles(
161	    x: number,
162	    y: number,
163	    color: readonly [number, number, number],
164	    speed: number,
165	  ): void {
166	    const count =
167	      Math.floor(speed * INTRO_CANVAS_MOTION.particleSpawnScale) +
168	      INTRO_CANVAS_MOTION.particleSpawnBaseCount;
169	    for (let i = 0; i < count; i += 1) {
170	      const angle =
171	        Math.PI +
172	        (Math.random() - 0.5) * INTRO_CANVAS_MOTION.particleAngleSpread;
173	      const velocity = Math.random() * speed * 2 + 0.5;
174	      this._particles.push({
175	        x,
176	        y,
177	        vx: Math.cos(angle) * velocity,
178	        vy: (Math.random() - 0.5) * velocity * 0.5,
179	        life: 1,
180	        decay:
181	          INTRO_CANVAS_MOTION.particleDecayBase +
182	          Math.random() * INTRO_CANVAS_MOTION.particleDecayRandom +
183	          velocity * INTRO_CANVAS_MOTION.particleDecaySpeedFactor,
184	        size: Math.random() * 2.4 + 0.4,
185	        rgb: color,
186	        bright: 0.65 + Math.random() * 0.7,
187	      });
188	    }
189	  }
190	
191	  private _drawFrame(progress: number, timestamp: number): void {
192	    const width = this.getWidth();
193	    const height = this.getHeight();
194	    const centerY = height / 2;
195	    const pulse =
196	      Math.sin(timestamp * INTRO_CANVAS_MOTION.pulseTimeScale * INTRO_CANVAS_MOTION.pulseFrequency) *
197	        0.5 +
198	      0.5;
199	
200	    this._context.clearRect(0, 0, width, height);
201	
202	    if (progress < INTRO_CANVAS_RENDER.minVisibleProgress) {
203	      this._particles = [];
204	      this._percentText.textContent = "0";
205	      return;
206	    }
207	
208	    const headX = this._mapProgressToX(progress, width);
209	    const color = this.getColorAt(progress);
210	
211	    this._drawParticles();
212	    this._drawTrail(headX, centerY, progress, color, width);
213	    this._drawTail(headX, centerY, color, width);
214	    this._drawHead(headX, centerY, color, pulse, width);
215	    this._percentText.textContent = String(Math.round(progress));
216	  }
217	
218	  private _mapProgressToX(progress: number, width: number): number {
219	    const edgeInset = INTRO_CANVAS_RENDER.headDotRadius + 4;
220	    return edgeInset + (progress / 100) * Math.max(0, width - edgeInset * 2);
221	  }
222	
223	  private _drawParticles(): void {
224	    this._particles = this._particles.filter((particle) => particle.life > 0.01);
225	    for (const particle of this._particles) {
226	      particle.x += particle.vx;
227	      particle.y += particle.vy;
228	      particle.vx *= INTRO_CANVAS_MOTION.particleVelocityDragX;
229	      particle.vy *= INTRO_CANVAS_MOTION.particleVelocityDragY;
230	      particle.life -= particle.decay;
231	      const alpha = Math.max(0, particle.life * particle.life);
232	      const rgb: [number, number, number] = [
233	        Math.min(255, Math.round(particle.rgb[0] * particle.bright)),
234	        Math.min(255, Math.round(particle.rgb[1] * particle.bright)),
235	        Math.min(255, Math.round(particle.rgb[2] * particle.bright)),
236	      ];
237	
238	      if (particle.size > INTRO_CANVAS_MOTION.particleLargeSizeThreshold) {
239	        this._context.beginPath();
240	        this._context.arc(
241	          particle.x,
242	          particle.y,
243	          particle.size * INTRO_CANVAS_MOTION.particleLargeRadiusScale,
244	          0,
245	          Math.PI * 2,
246	        );
247	        this._context.fillStyle = this.rgba(
248	          rgb,
249	          alpha * INTRO_CANVAS_MOTION.particleLargeAlphaScale,
250	        );
251	        this._context.fill();
252	      }
253	
254	      this._context.beginPath();
255	      this._context.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
256	      this._context.fillStyle = this.rgba(
257	        rgb,
258	        alpha * INTRO_CANVAS_MOTION.particleAlphaScale,
259	      );
260	      this._context.fill();
261	    }
262	  }
263	
264	  private _drawTrail(
265	    headX: number,
266	    centerY: number,
267	    progress: number,
268	    color: readonly [number, number, number],
269	    width: number,
270	  ): void {
271	    if (headX <= INTRO_CANVAS_RENDER.trailStartThreshold) return;
272	    const gradient = this._context.createLinearGradient(0, centerY, headX, centerY);
273	    gradient.addColorStop(0, this.rgba(INTRO_CANVAS_COLORS[0].color, 0));
274	    INTRO_CANVAS_COLORS.forEach((entry) => {
275	      if (entry.progress > progress) return;
276	      gradient.addColorStop(
277	        Math.min(entry.progress / progress, 1),
278	        this.rgba(entry.color, entry.progress / progress < 0.05 ? 0 : 0.55),
279	      );
280	    });
281	    gradient.addColorStop(1, this.rgba(color, 0.85));
282	
283	    this._context.beginPath();
284	    this._context.moveTo(0, centerY);
285	    this._context.lineTo(Math.min(headX, width), centerY);
286	    this._context.strokeStyle = gradient;
287	    this._context.lineWidth = INTRO_CANVAS_RENDER.lineWidth;
288	    this._context.stroke();
289	  }
290	
291	  private _drawTail(
292	    headX: number,
293	    centerY: number,
294	    color: readonly [number, number, number],
295	    width: number,
296	  ): void {
297	    if (headX <= INTRO_CANVAS_RENDER.tailStartThreshold) return;
298	    const tailLength = Math.min(
299	      width * INTRO_CANVAS_RENDER.tailMaxWidthRatio,
300	      INTRO_CANVAS_RENDER.tailMaxLength,
301	    );
302	    const tailStartX = Math.max(0, headX - tailLength);
303	    const gradient = this._context.createLinearGradient(
304	      tailStartX,
305	      centerY,
306	      headX,
307	      centerY,
308	    );
309	    gradient.addColorStop(0, this.rgba(color, 0));
310	    gradient.addColorStop(0.55, this.rgba(color, 0.08));
311	    gradient.addColorStop(0.85, this.rgba(color, 0.3));
312	    gradient.addColorStop(1, this.rgba(color, 0.65));
313	
314	    this._context.beginPath();
315	    this._context.moveTo(tailStartX, centerY);
316	    this._context.lineTo(headX, centerY);
317	    this._context.strokeStyle = gradient;
318	    this._context.lineWidth = INTRO_CANVAS_RENDER.tailLineWidth;
319	    this._context.shadowColor = this.rgba(color, 0.8);
320	    this._context.shadowBlur = INTRO_CANVAS_RENDER.tailShadowBlur;
321	    this._context.stroke();
322	    this._context.shadowBlur = 0;
323	  }
