344	        pulse * INTRO_CANVAS_RENDER.headOuterPulseRadius) *
345	        edgeFade,
346	    );
347	    outerHalo.addColorStop(0, this.rgba(color, 0.18 * edgeFade));
348	    outerHalo.addColorStop(0.3, this.rgba(color, 0.1 * edgeFade));
349	    outerHalo.addColorStop(1, this.rgba(color, 0));
350	    this._context.fillStyle = outerHalo;
351	    this._context.beginPath();
352	    this._context.arc(
353	      x,
354	      y,
355	      (INTRO_CANVAS_RENDER.headOuterRadius +
356	        pulse * INTRO_CANVAS_RENDER.headOuterPulseRadius) *
357	        edgeFade,
358	      0,
359	      Math.PI * 2,
360	    );
361	    this._context.fill();
362	
363	    const middleHalo = this._context.createRadialGradient(
364	      x,
365	      y,
366	      0,
367	      x,
368	      y,
369	      (INTRO_CANVAS_RENDER.headMiddleRadius +
370	        pulse * INTRO_CANVAS_RENDER.headMiddlePulseRadius) *
371	        edgeFade,
372	    );
373	    middleHalo.addColorStop(0, this.rgba([230, 246, 255], 0.55 * edgeFade));
374	    middleHalo.addColorStop(0.25, this.rgba(color, 0.45 * edgeFade));
375	    middleHalo.addColorStop(0.6, this.rgba(color, 0.15 * edgeFade));
376	    middleHalo.addColorStop(1, this.rgba(color, 0));
377	    this._context.fillStyle = middleHalo;
378	    this._context.beginPath();
379	    this._context.arc(
380	      x,
381	      y,
382	      (INTRO_CANVAS_RENDER.headMiddleRadius +
383	        pulse * INTRO_CANVAS_RENDER.headMiddlePulseRadius) *
384	        edgeFade,
