389	
390	    const flareHorizontal = this._context.createLinearGradient(
391	      x - (INTRO_CANVAS_RENDER.headHorizontalFlareWidth * edgeFade) / 2,
392	      y,
393	      x + (INTRO_CANVAS_RENDER.headHorizontalFlareWidth * edgeFade) / 2,
394	      y,
395	    );
396	    flareHorizontal.addColorStop(0, this.rgba(color, 0));
397	    flareHorizontal.addColorStop(0.45, this.rgba([230, 246, 255], (0.12 + pulse * 0.06) * edgeFade));
398	    flareHorizontal.addColorStop(0.5, this.rgba([255, 255, 255], (0.55 + pulse * 0.15) * edgeFade));
399	    flareHorizontal.addColorStop(0.55, this.rgba([230, 246, 255], (0.12 + pulse * 0.06) * edgeFade));
