417	    flareVertical.addColorStop(0.5, this.rgba([255, 255, 255], (0.35 + pulse * 0.1) * edgeFade));
418	    flareVertical.addColorStop(0.55, this.rgba([230, 246, 255], (0.08 + pulse * 0.04) * edgeFade));
