907	            `Invalid contact flow stage for success transition: ${this._contactFlowStage}`,
908	          );
909	        }
910	        this._contactFlowStage = "outtro";
911	        this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_LEAVING);
912	        await this._waitContactBackdropHidden();
913	        await this._playContactTheatreStep(
914	          this._engine,
915	          () => this._pageTheatreBinder.startAfterIntroIfNeeded(this._engine!),
916	        );
917	        this._syncContactSuccessMessage(detail.message);
918	        this._contactFlowStage = "success";
919	        this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_SUCCESS);
920	      });
921	      detail.resolve();
922	    } catch (error) {
923	      this._contactFlowStage = "ready";
924	      this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_READY);
