933	      this._contactFlowStage === "success"
934	    ) {
935	      return;
936	    }
937	    if (this._contactIntroTask) {
938	      await this._contactIntroTask;
939	      return;
940	    }
941	
942	    this._contactIntroTask = this._enqueueContactFlow(async () => {
943	      if (this._contactFlowStage !== "idle") return;
