1026	    blocks.forEach((block) => {
1027	      block.classList.remove("is-block-reveal-down");
1028	    });
1029	    BlockReveal.prepare(blocks);
1030	    BlockReveal.prepare(this._resolveContactSuccessBlocks());
1031	
1032	    const successTextNodes = this._resolveContactSuccessTextNodes();
1033	    successTextNodes.forEach((node) => {
