4	const INTRO_PANEL_SELECTOR = "#intro-card";
5	const INTRO_PERCENT_SELECTOR = "#pct-text";
6	const INTRO_PROGRESS_HOLD_MAX = 96;
7	const INTRO_PROGRESS_STEP_MIN = 0.1;
8	const INTRO_PROGRESS_EASE = 0.028;
9	const INTRO_PROGRESS_MIN_DURATION_MS = 2200;
10	const INTRO_FINISH_DURATION = 1.65;
11	const EXIT_CLIP_DELAY = 0.6;
