13	class IntroLoadingPanel {
14	  private readonly _panel: HTMLElement | null;
15	  private readonly _percentValue: HTMLElement | null;
16	
17	  constructor() {
18	    if (typeof document === "undefined") {
19	      this._panel = null;
20	      this._percentValue = null;
21	      return;
22	    }
23	    this._panel = document.querySelector<HTMLElement>(INTRO_PANEL_SELECTOR);
24	    this._percentValue = document.querySelector<HTMLElement>(
25	      INTRO_PERCENT_SELECTOR,
26	    );
27	  }
28	
29	  reset(): void {
30	    this.show();
31	    this._setPercentText(0);
32	    this._progressBridge()?.reset?.();
33	  }
34	
35	  show(): void {
36	    if (!this._panel) return;
37	    this._panel.style.opacity = "1";
38	    this._panel.style.transform = "translate3d(0, 0, 0) scale(1)";
39	    this._panel.style.clipPath = "inset(0 0 0 0)";
40	  }
41	
42	  setProgress(progress: number): void {
43	    const clamped = Math.max(0, Math.min(100, progress));
44	    this._setPercentText(clamped);
45	    this._progressBridge()?.set?.(clamped);
46	  }
47	
48	  private _setPercentText(progress: number): void {
49	    if (!this._percentValue) return;
50	    this._percentValue.textContent = `${Math.round(progress)}`;
51	  }
52	
53	  private _progressBridge():
54	    | {
55	        reset?: () => void;
56	        set?: (value: number) => void;
57	      }
58	    | undefined {
59	    if (typeof window === "undefined") return undefined;
60	    return (
61	      window as Window & {
62	        __introProgress?: {
63	          reset?: () => void;
64	          set?: (value: number) => void;
65	        };
66	      }
67	    ).__introProgress;
68	  }
69	}
