71	export async function runIntroLoadingProgress(
72	  loadPromise: Promise<void> | undefined,
73	  gsapApi: IntroRunContext["gsap"],
74	): Promise<void> {
75	  if (!loadPromise) return;
76	  const panel = new IntroLoadingPanel();
77	  panel.reset();
78	  let progress = 0;
79	  let isSettled = false;
80	  let frameId: number | null = null;
81	  const minDurationPromise = new Promise<void>((resolve) => {
82	    window.setTimeout(resolve, INTRO_PROGRESS_MIN_DURATION_MS);
83	  });
84	  const tick = (): void => {
85	    if (isSettled) return;
86	    progress = Math.min(
87	      INTRO_PROGRESS_HOLD_MAX,
88	      progress +
89	        Math.max(
90	          INTRO_PROGRESS_STEP_MIN,
91	          (INTRO_PROGRESS_HOLD_MAX - progress) * INTRO_PROGRESS_EASE,
92	        ),
93	    );
94	    panel.setProgress(progress);
95	    frameId = window.requestAnimationFrame(tick);
96	  };
97	
98	  panel.setProgress(0);
99	  frameId = window.requestAnimationFrame(tick);
100	  try {
101	    await Promise.all([loadPromise, minDurationPromise]);
102	  } finally {
103	    isSettled = true;
104	    if (frameId !== null) window.cancelAnimationFrame(frameId);
105	  }
106	
107	  if (!gsapApi) {
108	    panel.setProgress(100);
109	    return;
110	  }
111	
112	  await new Promise<void>((resolve) => {
113	    const progressState = { value: progress };
114	    gsapApi.to(progressState, {
115	      value: 100,
116	      duration: INTRO_FINISH_DURATION,
117	      ease: "power2.out",
118	      onUpdate: () => panel.setProgress(progressState.value),
119	      onComplete: () => {
120	        panel.setProgress(100);
121	        resolve();
122	      },
123	    });
124	  });
125	}
126	
127	export function runIntroDomTimeline(
128	  tl: GSAPTimeline,
129	  ctx?: IntroRunContext,
130	): GSAPTimeline {
131	  const loadPromise = ctx?.loadPromise;
132	  const panel = new IntroLoadingPanel();
133	  tl.addLabel("introEnter", 0);
134	  tl.add(() => panel.reset(), "introEnter");
135	  tl.addLabel("introProgressStart", "introEnter");
136	
137	  if (loadPromise) {
138	    tl.add(
139	      () =>
140	        ctx?.controller?.runWaitPromise(
141	          runIntroLoadingProgress(loadPromise as Promise<void>, ctx?.gsap),
142	        ),
143	      "introProgressStart",
144	    );
145	  }
146	
147	  tl.addLabel("introExit", ">").to(
148	    INTRO_PANEL_SELECTOR,
149	    {
150	      clipPath: "inset(0 0 100% 0)",
151	      duration: EXIT_CLIP_DELAY,
152	      ease: "power2.inOut",
153	    },
154	    "introExit",
155	  );
156	  return tl;
157	}
